    ["Comfort <h> Leon </>"] = "РљРѕРјС„РѕСЂС‚ <h> Р›РµРѕРЅ </>",
    ["дєєз‰©жѕз¤єдёЌе®Њж•ґпјЊиЇ·зЎ®дїќеЊ…еђ«е…Ёиє«"] = "РџРµСЂСЃРѕРЅР°Р¶ РІРёРґРµРЅ РЅРµ РїРѕР»РЅРѕСЃС‚СЊСЋ; РїРѕР¶Р°Р»СѓР№СЃС‚Р°, СѓР±РµРґРёС‚РµСЃСЊ, С‡С‚Рѕ РІ РєРѕРјРїР»РµРєС‚ РІС…РѕРґРёС‚ РІСЃРµ С‚РµР»Рѕ.",
    ["I requested the Sealed Artifact \"Paradox of Luck\". In a crisis, I hope it brings enough luck."] = "РЇ Р·Р°РїСЂРѕСЃРёР» Р—Р°РїРµС‡Р°С‚Р°РЅРЅС‹Р№ РђСЂС‚РµС„Р°РєС‚ В«РџР°СЂР°РґРѕРєСЃ РЈРґР°С‡РёВ». Р’ РєСЂРёР·РёСЃ, СЏ РЅР°РґРµСЋСЃСЊ, СЌС‚Рѕ РїСЂРёРЅРµСЃРµС‚ РґРѕСЃС‚Р°С‚РѕС‡РЅРѕ СѓРґР°С‡Рё.",
    ["The group leader changed the group name and announcement."] = "Р›РёРґРµСЂ РіСЂСѓРїРїС‹ РёР·РјРµРЅРёР» РЅР°Р·РІР°РЅРёРµ РіСЂСѓРїРїС‹ Рё РѕР±СЉСЏРІР»РµРЅРёРµ.",
    ["дЅ†ењЁж­ЈејЏејЂе§‹д№‹е‰ЌпјЊдЅ йњЂи¦Ѓдє†и§ЈжњЂеџєзЎЂзљ„зџҐиЇ†гЂ‚"] = "РќРѕ РїСЂРµР¶РґРµ С‡РµРј РјС‹ РѕС„РёС†РёР°Р»СЊРЅРѕ РЅР°С‡РЅРµРј, РІР°Рј РЅРµРѕР±С…РѕРґРёРјРѕ РїРѕРЅСЏС‚СЊ РѕСЃРЅРѕРІС‹.",
